<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$id=(int)($_GET['id']??0);$pdo=db();$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND seller_id=?');$s->execute([$id,$sid]);$p=$s->fetch();if(!$p){flash('error','Listing not found.');redirect('seller/products.php');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$price=(float)post('price');$stock=(float)post('stock');$min=(float)post('min_quantity');if(!post('name')||$price<=0||$stock<0||$min<=0||($stock>0&&$min>$stock))$error='Check required values and stock quantities.';else{$old=$p['image_path'];$image=$old;try{$new=upload_product_image($_FILES['image']??[]);if($new)$image=$new;elseif(isset($_POST['remove_image']))$image=null;$pdo->prepare('UPDATE products SET category_id=?,name=?,description=?,image_path=?,price=?,stock=?,min_quantity=?,freshness_info=?,is_available=? WHERE id=? AND seller_id=?')->execute([(int)post('category_id'),post('name'),post('description'),$image,$price,$stock,$min,post('freshness_info'),isset($_POST['is_available']),$id,$sid]);if($old!==$image)delete_product_upload($old);flash('success','Listing updated.');redirect('seller/products.php');}catch(Throwable $e){$error=$e->getMessage();}}}$pageTitle='Edit listing';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER CATALOGUE</p><h1>Edit <?=e($p['name'])?></h1></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><?php require 'product-form.php';require '../includes/footer.php'; ?>
